// L298N: IN1 and IN2 pick motor A's direction, IN3 and IN4 motor B's
const int ENA = 9, IN1 = 8, IN2 = 7;   // motor A: enable and the two direction inputs
const int ENB = 3, IN3 = 5, IN4 = 4;   // motor B

void drive(int in1, int in2, int in3, int in4) {
  digitalWrite(IN1, in1); digitalWrite(IN2, in2);
  digitalWrite(IN3, in3); digitalWrite(IN4, in4);
}

void setup() {
  for (int p = 3; p <= 9; p++) pinMode(p, OUTPUT);
  Serial.begin(9600);
  analogWrite(ENA, 255);      // full speed (the cap holds ENA at 5 V anyway)
  analogWrite(ENB, 255);
  drive(HIGH, HIGH, HIGH, HIGH);   // equal inputs: both motor leads on the same rail, a fast stop
  Serial.println("brake: IN1 = IN2, IN3 = IN4");
}

void loop() {
}

